<template><p v-if="error" class="wb-notice error">{{error}}</p><div v-if="data"><section class="wb-metrics"><article><label>旧选股阶段记录</label><strong>{{data.record_count ?? '—'}}</strong><small>{{data.days}}个日期</small></article><article><label>去重种子 / 有早盘分钟</label><strong>{{data.seed_count}} / {{data.coverage?.['有早盘分钟的种子']||0}}</strong><small>主库 + 备份库 + 冷库</small></article><article><label>规则通过且路径完整</label><strong>{{data.trades?.length||0}}</strong><small>两阶段可能有同一股票，非独立交易组合</small></article><article><label>规则重建</label><strong>09:31 / 09:40</strong><small>承接确认 / 修复确认</small></article></section><section class="wb-panel"><h3>旧策略历史重建 · 固定持有期对照</h3><p>{{data.note}}</p><div class="wb-table-scroll"><table class="wb-table"><thead><tr><th>确认时点</th><th>买入后持有</th><th>相同样本数</th><th>价格上涨占比</th><th>平均价格变化</th></tr></thead><tbody><tr v-for="r in data.comparisons||[]" :key="r.stage+r.hold"><td>{{r.stage}}</td><td>{{r.hold}}个交易日</td><td>{{r.count}}</td><td>{{r.positive_rate==null?'—':r.positive_rate+'%'}}</td><td>{{r.mean_price_change==null?'—':r.mean_price_change+'%'}}</td></tr></tbody></table></div><details><summary>记录时点审计与数据缺口</summary><div class="wb-tags"><span v-for="(v,k) in data.strict_record_audit" :key="k">{{k}}：{{v}}</span></div><p v-for="(v,k) in data.excluded" :key="k" class="wb-footnote">{{k}} · {{v}}</p></details></section><section class="wb-panel"><div class="wb-panel-title"><h3>逐笔价格路径</h3><input v-model="search" placeholder="代码 / 日期 / 名称" aria-label="搜索旧策略回溯"/></div><div class="wb-table-scroll"><table class="wb-table"><thead><tr><th>日期 / 标的</th><th>规则阶段</th><th>下一分钟参考价</th><th>T+1</th><th>T+3</th><th>T+5</th></tr></thead><tbody><tr v-for="(t,i) in filtered.slice(0,limit)" :key="i"><td>{{t.day}}<small>{{t.name}} {{t.code}}</small></td><td>{{t.stage}}</td><td>{{t.entry_time}} · {{t.entry_price}}</td><td v-for="p in t.paths" :key="p.hold" :class="p.price_change_pct>0?'wb-up':'wb-down'">{{p.price_change_pct}}%<small>{{p.exit_date}}</small></td></tr></tbody></table></div><button v-if="filtered.length>limit" class="wb-button" @click="limit+=50">继续显示 {{filtered.length-limit}} 条</button></section></div></template>
<script setup>
import {ref,computed,onMounted} from 'vue'
import axios from 'axios'
const data=ref(),error=ref(''),search=ref(''),limit=ref(30),filtered=computed(()=>(data.value?.trades||[]).filter(t=>(t.day+t.code+t.name).includes(search.value)))
onMounted(async()=>{try{data.value=(await axios.get('/api/workbench/legacy-replay')).data}catch{error.value='旧策略报告读取失败'}})
</script>
